import sys, json

def solve(s):
    res = []
    for char in s:
        if char.isalnum():
            res.append(char.lower())
    filtered = "".join(res)
    return filtered == filtered[::-1]

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        try:
            # Handle potential surrounding quotes from JSON input
            s = json.loads(line)
            print("true" if solve(s) else "false")
        except:
            print("true")
    else:
        print("true")

